ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/"questions/social";LESSON="lesson-social-content-hist-kb-iv-2";KG="kg-social-content-hist-kb-iv-2";TARGETS=["A","B","C","D","A","B","C","D","B","C"]
