 p=OUT/f"question-social-content-hist-kb-iv-2-{i}.json";d=json.loads(p.read_text(encoding="utf-8"));assert d["lessonId"]==LESSON and d["knowledgeIds"]==[KG];old=d["answer"]["value"];oi=ord(old)-65;correct=d["options"][oi]["text"];rest=[x["text"]for j,x in enumerate(d["options"])if j!=oi];ti=ord(target)-65;ordered=rest[:ti]+[correct]+rest[ti:];d["options"]=[{"id":chr(65+j),"text":x}for j,x in enumerate(ordered)];focus,reason=FOCI[i-1]
